const requestLibrarySync = `-- name: RequestLibrarySync :execrows
INSERT INTO library_syncs (media_server_id, state)
VALUES ($1, 'pending')
ON CONFLICT (media_server_id) DO UPDATE SET
    state = 'pending', cursor = '', seen_count = 0, upserted_count = 0,
    archived_count = 0, last_error = '', lease_token = '', lease_expires_at = NULL,
    started_at = NULL, finished_at = NULL
WHERE library_syncs.state NOT IN ('pending', 'running')
`

func (q *Queries) RequestLibrarySync(ctx context.Context, mediaServerID string) (int64, error) {
	result, err := q.db.ExecContext(ctx, requestLibrarySync, mediaServerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const selectClaimableLibrarySync = `-- name: SelectClaimableLibrarySync :one
SELECT media_server_id, state, cursor, seen_count, upserted_count, archived_count, last_error, lease_token, lease_expires_at, started_at, finished_at FROM library_syncs
WHERE state = 'pending'
   OR (state = 'running' AND lease_expires_at <= $1)
   OR (state IN ('completed', 'failed') AND finished_at <= $2)
ORDER BY CASE WHEN state = 'pending' THEN 0 WHEN state = 'running' THEN 1 ELSE 2 END,
         finished_at, media_server_id
LIMIT 1
`

type SelectClaimableLibrarySyncParams struct {
	Now       sql.NullTime
	DueBefore sql.NullTime
}

func (q *Queries) SelectClaimableLibrarySync(ctx context.Context, arg SelectClaimableLibrarySyncParams) (LibrarySync, error) {
	row := q.db.QueryRowContext(ctx, selectClaimableLibrarySync, arg.Now, arg.DueBefore)
	var i LibrarySync
	err := row.Scan(
		&i.MediaServerID,
		&i.State,
		&i.Cursor,
		&i.SeenCount,
		&i.UpsertedCount,
		&i.ArchivedCount,
		&i.LastError,
		&i.LeaseToken,
		&i.LeaseExpiresAt,
		&i.StartedAt,
		&i.FinishedAt,
	)
	return i, err
}

